<?php
declare(strict_types=1);namespace App\Interface\Http\Discovery;use App\Application\Discovery\Mapper\DiscoveryResponseMapper;use App\Application\Discovery\Service\DiscoverWebResourcesService;use App\Application\Discovery\Service\ListDiscoveryResourcesService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Discovery\ConfiguredWebDiscoveryProvider;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\Discovery\DoctrineDiscoveryResourceRepository;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Interface\Http\Discovery\Controller\DiscoveryController;use App\Interface\Http\Identity\IdentityRequestFactory;use InvalidArgumentException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;final class DiscoveryRouteRegistrar{public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$repo=new DoctrineDiscoveryResourceRepository(DoctrineEntityManagerFactory::create());$mapper=new DiscoveryResponseMapper();$c=new DiscoveryController($this->auth,new DiscoverWebResourcesService($repo,new ConfiguredWebDiscoveryProvider(),$mapper),new ListDiscoveryResourcesService($repo,$mapper),$this->responses);$i=new IdentityRequestFactory();$f=new DiscoveryRequestFactory();$responses=$this->responses;$app->get('/v1/admin/discovery/resources',static function(ServerRequestInterface $r,ResponseInterface $s)use($c,$i,$responses):ResponseInterface{try{$type=$r->getQueryParams()['type']??null;return $c->list($r,$s,$i->accessToken($r),is_string($type)?$type:null);}catch(InvalidArgumentException $e){return $responses->problem($s,'MALFORMED_REQUEST',$e->getMessage(),400,(string)$r->getAttribute('request_id'));}});$app->post('/v1/admin/discovery/searches',static function(ServerRequestInterface $r,ResponseInterface $s)use($c,$i,$f,$responses):ResponseInterface{try{return $c->search($r,$s,$i->accessToken($r),$f->search($r));}catch(InvalidArgumentException $e){return $responses->problem($s,'MALFORMED_REQUEST',$e->getMessage(),400,(string)$r->getAttribute('request_id'));}});}}
